WITH matched_keys AS (SELECT customer_id, status FROM orders INTERSECT SELECT customer_id, status FROM orders WHERE status = 'SHIPPED'), kept_rows AS (SELECT s.* FROM orders s JOIN matched_keys k ON s.customer_id = k.customer_id AND s.status = k.status) SELECT customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, CASE WHEN channel RLIKE '^(partner|mobile)$' THEN 'CORE' ELSE 'PRIORITY' END AS channel_zone FROM kept_rows ORDER BY channel_zone DESC NULLS FIRST, store_id DESC;
